\copy (SELECT table_name||'|'||column_name||'|'||data_type||'|'||is_nullable||'|'||coalesce(column_default,'') FROM information_schema.columns WHERE table_schema='public' AND table_name IN ('transactions','cards','user_cards','ledger_entries','bill_payments','crypto_wallets','fraud_alerts','savings_accounts','investments','investment_price_snapshots','user_budgets','conversions','voice_commands','content_completions') ORDER BY table_name, ordinal_position) TO 'emptycols.out' WITH (FORMAT csv)
